correct_example.code:
contract RewardDistributor {
    CToken public cDAI;

    function depositAndClaim(uint256 amount) external {
        cDAI.mint(amount);
        cDAI.accrueInterest(); // ensure latest index
        uint256 underlying = cDAI.balanceOfUnderlying(msg.sender); // @audit reads post-action rate
        uint256 reward = underlying * rewardPerToken / 1e18;
        rewardToken.mint(msg.sender, reward);
    }
}
